CREATE TABLE public.family(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, created_by uuid NOT NULL DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.family TO authenticated; GRANT ALL ON public.family TO service_role; ALTER TABLE public.family ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.family_member(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), family_id uuid NOT NULL REFERENCES public.family(id), user_id uuid NOT NULL, name text NOT NULL DEFAULT 'Family member', UNIQUE(family_id,user_id));
GRANT SELECT ON public.family_member TO authenticated; GRANT ALL ON public.family_member TO service_role; ALTER TABLE public.family_member ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.user_roles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), family_id uuid NOT NULL REFERENCES public.family(id), user_id uuid NOT NULL, role text NOT NULL CHECK(role IN ('Owner','Adult','Dependent')), UNIQUE(family_id,user_id));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role; ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.family_role(p_family uuid) RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT role FROM public.user_roles WHERE family_id=p_family AND user_id=auth.uid() $$;
REVOKE ALL ON FUNCTION public.family_role(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.family_role(uuid) TO authenticated;
CREATE POLICY family_read ON public.family FOR SELECT TO authenticated USING(public.family_role(id) IS NOT NULL);
CREATE POLICY members_read ON public.family_member FOR SELECT TO authenticated USING(public.family_role(family_id) IS NOT NULL);
CREATE POLICY roles_read ON public.user_roles FOR SELECT TO authenticated USING(public.family_role(family_id) IS NOT NULL);
CREATE TABLE public.account(id text NOT NULL, family_id uuid NOT NULL REFERENCES public.family(id), payload jsonb NOT NULL, PRIMARY KEY(family_id,id));
GRANT SELECT ON public.account TO authenticated; GRANT ALL ON public.account TO service_role; ALTER TABLE public.account ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.category(id text NOT NULL, family_id uuid NOT NULL REFERENCES public.family(id), payload jsonb NOT NULL, PRIMARY KEY(family_id,id));
GRANT SELECT ON public.category TO authenticated; GRANT ALL ON public.category TO service_role; ALTER TABLE public.category ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.transaction(id text NOT NULL, family_id uuid NOT NULL REFERENCES public.family(id), payload jsonb NOT NULL, PRIMARY KEY(family_id,id));
GRANT SELECT ON public.transaction TO authenticated; GRANT ALL ON public.transaction TO service_role; ALTER TABLE public.transaction ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.budget(id text NOT NULL, family_id uuid NOT NULL REFERENCES public.family(id), payload jsonb NOT NULL, PRIMARY KEY(family_id,id));
GRANT SELECT ON public.budget TO authenticated; GRANT ALL ON public.budget TO service_role; ALTER TABLE public.budget ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.savings_goal(id text NOT NULL, family_id uuid NOT NULL REFERENCES public.family(id), payload jsonb NOT NULL, PRIMARY KEY(family_id,id));
GRANT SELECT ON public.savings_goal TO authenticated; GRANT ALL ON public.savings_goal TO service_role; ALTER TABLE public.savings_goal ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.goal_contribution(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), family_id uuid NOT NULL REFERENCES public.family(id), goal_id text NOT NULL, amount numeric(14,2) NOT NULL CHECK(amount>0), user_id uuid NOT NULL DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(family_id,goal_id) REFERENCES public.savings_goal(family_id,id));
GRANT SELECT ON public.goal_contribution TO authenticated; GRANT ALL ON public.goal_contribution TO service_role; ALTER TABLE public.goal_contribution ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.bill_subscription(id text NOT NULL, family_id uuid NOT NULL REFERENCES public.family(id), payload jsonb NOT NULL, PRIMARY KEY(family_id,id));
GRANT SELECT ON public.bill_subscription TO authenticated; GRANT ALL ON public.bill_subscription TO service_role; ALTER TABLE public.bill_subscription ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.expense_split(id text NOT NULL, family_id uuid NOT NULL REFERENCES public.family(id), payload jsonb NOT NULL, PRIMARY KEY(family_id,id));
GRANT SELECT ON public.expense_split TO authenticated; GRANT ALL ON public.expense_split TO service_role; ALTER TABLE public.expense_split ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.audit_log(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), family_id uuid NOT NULL REFERENCES public.family(id), user_id uuid NOT NULL DEFAULT auth.uid(), action text NOT NULL, detail text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.audit_log TO authenticated; GRANT ALL ON public.audit_log TO service_role; ALTER TABLE public.audit_log ENABLE ROW LEVEL SECURITY;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['account','category','transaction','budget','savings_goal','goal_contribution','bill_subscription','expense_split','audit_log'] LOOP EXECUTE format('CREATE POLICY family_read ON public.%I FOR SELECT TO authenticated USING (public.family_role(family_id) IS NOT NULL)',t); END LOOP; END $$;
CREATE FUNCTION public.create_household(p_name text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE f uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; IF length(trim(p_name))<2 OR length(p_name)>80 THEN RAISE EXCEPTION 'Invalid household name'; END IF; SELECT family_id INTO f FROM public.family_member WHERE user_id=auth.uid() LIMIT 1; IF f IS NOT NULL THEN RETURN f; END IF; INSERT INTO public.family(name,created_by) VALUES(p_name,auth.uid()) RETURNING id INTO f; INSERT INTO public.family_member(family_id,user_id,name) VALUES(f,auth.uid(),'Owner'); INSERT INTO public.user_roles(family_id,user_id,role) VALUES(f,auth.uid(),'Owner'); RETURN f; END $$;
REVOKE ALL ON FUNCTION public.create_household(text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.create_household(text) TO authenticated;
CREATE FUNCTION public.read_finance(p_family uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result jsonb := '{}'::jsonb; t text; k text; arr jsonb; BEGIN IF public.family_role(p_family) IS NULL THEN RAISE EXCEPTION 'Not a household member'; END IF; FOR t,k IN SELECT * FROM (VALUES('account','accounts'),('budget','budgets'),('transaction','transactions'),('savings_goal','goals'),('bill_subscription','bills'),('expense_split','splits')) m(t,k) LOOP EXECUTE format('SELECT coalesce(jsonb_agg(payload),''[]''::jsonb) FROM public.%I WHERE family_id=$1',t) INTO arr USING p_family; result := result || jsonb_build_object(k,arr); END LOOP; SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'action',action,'detail',detail,'date',created_at,'member','Household member') ORDER BY created_at DESC),'[]'::jsonb) INTO arr FROM public.audit_log WHERE family_id=p_family; result:=result||jsonb_build_object('audit',arr); RETURN jsonb_build_object('state',result,'role',public.family_role(p_family)); END $$;
REVOKE ALL ON FUNCTION public.read_finance(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.read_finance(uuid) TO authenticated;
CREATE FUNCTION public.save_finance(p_family uuid,p_state jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE t text; k text; item jsonb; old_saved numeric; new_saved numeric; BEGIN IF coalesce(public.family_role(p_family),'') NOT IN ('Owner','Adult') THEN RAISE EXCEPTION 'Only Owners and Adults can edit household finances'; END IF; PERFORM 1 FROM public.family WHERE id=p_family FOR UPDATE; IF octet_length(p_state::text)>1000000 THEN RAISE EXCEPTION 'Household data too large'; END IF; FOR t,k IN SELECT * FROM (VALUES('account','accounts'),('budget','budgets'),('transaction','transactions'),('savings_goal','goals'),('bill_subscription','bills'),('expense_split','splits')) m(t,k) LOOP IF jsonb_typeof(p_state->k)<>'array' THEN RAISE EXCEPTION 'Invalid finance data'; END IF; FOR item IN SELECT value FROM jsonb_array_elements(p_state->k) LOOP IF t IN ('transaction','bill_subscription','expense_split') AND ((item->>'amount')::numeric<=0 OR (item->>'amount')::numeric>1000000000) THEN RAISE EXCEPTION 'Amount must be positive and within limits'; END IF; IF t='transaction' AND item->>'type' NOT IN ('income','expense') THEN RAISE EXCEPTION 'Invalid transaction type'; END IF; IF t='budget' AND (item->>'limit')::numeric<=0 THEN RAISE EXCEPTION 'Budget must be positive'; END IF; IF t='savings_goal' THEN IF (item->>'target')::numeric<=0 OR (item->>'saved')::numeric<0 OR (item->>'saved')::numeric>(item->>'target')::numeric THEN RAISE EXCEPTION 'Invalid savings goal'; END IF; SELECT (payload->>'saved')::numeric INTO old_saved FROM public.savings_goal WHERE family_id=p_family AND id=item->>'id'; new_saved:=(item->>'saved')::numeric; END IF; EXECUTE format('INSERT INTO public.%I(id,family_id,payload) VALUES($1,$2,$3) ON CONFLICT(family_id,id) DO UPDATE SET payload=excluded.payload',t) USING coalesce(item->>'id',item->>'name'),p_family,item; IF t='savings_goal' AND old_saved IS NOT NULL AND new_saved>old_saved THEN INSERT INTO public.goal_contribution(family_id,goal_id,amount) VALUES(p_family,item->>'id',new_saved-old_saved); END IF; IF t='budget' THEN INSERT INTO public.category(id,family_id,payload) VALUES(item->>'name',p_family,jsonb_build_object('name',item->>'name')) ON CONFLICT DO NOTHING; END IF; END LOOP; END LOOP; INSERT INTO public.audit_log(family_id,action,detail) VALUES(p_family,'Household finances updated','Accounts, transactions, goals, bills and splits saved by authenticated member'); END $$;
REVOKE ALL ON FUNCTION public.save_finance(uuid,jsonb) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.save_finance(uuid,jsonb) TO authenticated;